test "t09 colapsar espacios" {
    const cases = [_][]const u8{ "  hola\t  mundo\n ", "   ", "un", "a  b" };
    const expected = [_][]const u8{ "hola mundo", "", "un", "a b" };
    for (cases, expected) |input, want| {
        const got = try collapseSpaces(std.testing.allocator, input);
        defer std.testing.allocator.free(got);
        try std.testing.expectEqualStrings(want, got);
    }
}
